insert into public.quizzes(id,title,curriculum) values('11111111-1111-4111-8111-111111111111','SeniBahasa Adventure 3.0','SK 4.1 / SP 4.1.1') on conflict(id) do nothing;
insert into public.questions(quiz_id,ordinal,level,prompt,options,answer_index,feedback) values
('11111111-1111-4111-8111-111111111111',1,'Sukar','Pilih dialog yang menggunakan peribahasa dengan tepat dan santun.','["Pak Mail ringan tulang; beliau membantu kami mengangkat bakul.","Pak Mail ringan tulang, tulangnya tentu tidak berat.","Ringan tulang! Awak pemalas.","Ringan tulang."]',0,'Peribahasa digunakan dalam dialog lengkap dan sesuai.'),
('11111111-1111-4111-8111-111111111111',2,'Sukar','Dua sahabat saling membantu membina jambatan. Pilih dialog sesuai.','["Bagai aur dengan tebing, kita saling membantu.","Aur itu bahan jambatan.","Kamu tidak berguna.","Jom cepat."]',0,'Peribahasa ini menggambarkan sikap saling membantu.'),
('11111111-1111-4111-8111-111111111111',3,'Sukar','Pilih nasihat berperibahasa yang santun kepada rakan yang sedang belajar.','["Genggam bara api biar sampai jadi arang; teruskan berusaha.","Genggam bara api! Awak menyusahkan.","Genggam bara api.","Awak akan gagal."]',0,'Nasihat itu menggalakkan ketekunan dengan santun.'),
('11111111-1111-4111-8111-111111111111',4,'Sederhana','Nadia membaca kerana yakin ilmu menerangi kehidupan.','["Ilmu pelita hidup","Seperti katak di bawah tempurung","Bagai mencurah air ke daun keladi","Harapkan pagar, pagar makan padi"]',0,'Ilmu menjadi panduan kehidupan seperti pelita yang menerangi.'),
('11111111-1111-4111-8111-111111111111',5,'Sederhana','Peribahasa tentang usaha yang meningkatkan kebolehan ialah…','["Belakang parang pun jika diasah nescaya tajam","Bagai enau dalam belukar","Seperti pungguk rindukan bulan","Bagai telur di hujung tanduk"]',0,'Latihan dan usaha meningkatkan kebolehan.'),
('11111111-1111-4111-8111-111111111111',6,'Sederhana','Pilih peribahasa yang sesuai untuk dialog tentang kerjasama.','["Berat sama dipikul, ringan sama dijinjing","Ada gula, ada semut","Seperti rusa masuk kampung","Biar putih tulang"]',0,'Ungkapan ini mengajak semua orang berkongsi tugas.'),
('11111111-1111-4111-8111-111111111111',7,'Sederhana','Usaha sedikit demi sedikit akhirnya membawa hasil.','["Sehari selembar benang, lama-lama menjadi kain","Bagai mencurah air ke daun keladi","Nasi sudah menjadi bubur","Seperti anjing dengan kucing"]',0,'Usaha kecil yang berterusan membawa hasil.'),
('11111111-1111-4111-8111-111111111111',8,'Mudah','Peribahasa yang bermaksud rajin membantu ialah…','["Ringan tulang","Panjang tangan","Mulut tempayan","Kaki bangku"]',0,'Ringan tulang bermaksud rajin membantu.'),
('11111111-1111-4111-8111-111111111111',9,'Mudah','Dua orang yang selalu bergaduh seperti…','["Anjing dengan kucing","Isi dengan kuku","Aur dengan tebing","Pinang dibelah dua"]',0,'Seperti anjing dengan kucing bermaksud selalu bergaduh.'),
('11111111-1111-4111-8111-111111111111',10,'Mudah','“Buah tangan” bermaksud…','["Hadiah atau cenderamata","Buah yang dipetik","Kerja yang belum siap","Orang yang suka menolong"]',0,'Buah tangan ialah hadiah atau cenderamata.') on conflict(quiz_id,ordinal) do nothing;
